CREATE TABLE IF NOT EXISTS safeguarding_requirements (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',subject_component TEXT NOT NULL,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,title TEXT NOT NULL,requirement_type TEXT NOT NULL CHECK(requirement_type IN ('supervision','access_control','consent','staffing','communication','other')),operational_instruction TEXT NOT NULL,owner_type TEXT NOT NULL DEFAULT 'user',owner_id TEXT NOT NULL,due_at TEXT,verification_notes TEXT,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','verified','not_applicable','withdrawn')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE INDEX IF NOT EXISTS idx_safeguarding_subject ON safeguarding_requirements(app_id,subject_component,subject_type,subject_id,status);
